    rakamlar = rakamlar.slice(2) // +90 ile başlıyorsa 90'ı çıkar
  } else if (rakamlar.startsWith('0')) {
    rakamlar = rakamlar.slice(1) // 0 ile başlıyorsa 0'ı çıkar
